  const navigate = useNavigation();
  const intl = useIntl();
  // Same split product-list/productListCardMapper.ts's own consumer uses
  // (product-list/index.tsx): passed into the mapper rather than formatted there, keeping that
  // mapper free of any react-intl dependency of its own.
  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });

  const ref = useRef();
  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
  const [_products, setProducts] = useState(products);
  // Cart-exclusion check (2026-09-10, Marcel: "no recently viewed on cart" — a standing product
  // decision, not an Einstein-not-deployed-yet placeholder). Cart has no Zimmermann override
  // (no overrides/app/pages/cart/ at all) — its base page imports this same overridden component
  // and passes `recommender={EINSTEIN_RECOMMENDERS.CART_RECENTLY_VIEWED}`, which resolves to the
  // exact same string as PDP_RECENTLY_VIEWED (confirmed identical,
  // node_modules/.../constants.js:154-160), so the recommender check below cannot tell the two
  // apart by value alone. `.endsWith('/cart')`, not an exact match — AGENTS.md's Multi-site
  // section: a real storefront path is locale/site-prefixed (e.g. `/en-GB/cart`), so an exact
  // `=== '/cart'` would only ever match the default site.
  const location = useLocation();
  const isCartPage = location.pathname.endsWith('/cart');
  // Unconditional, alongside the hook calls above — must run on every render, including the
  // ones that hit the dead-code early returns further below, per React's rules of hooks.
  const { hasRecentlyViewed, recentlyViewedIds } = useRecentlyViewedHistory();
  // The See-Full-History trigger threshold, resolved for whichever breakpoint is actually
  // current. Also unconditional per rules of hooks; only meaningful inside the Recently-Viewed
  // branch below, same as the two hooks immediately above. Reads the current breakpoint only — no
  // ResizeObserver, no runtime DOM measurement, matching the AC's own viewport-relative "exceeds
  // the visible rail width" wording (Open Question 1). See the module docblock's own "See-Full-
  // History link" section for why this is no longer a plain `useBreakpointValue` call.
  const visibleCardCount = useRecentlyViewedRailVisibleCount();
  // `buildUrl` site/locale-prefixes an internal path (e.g. `/en-GB/recently-viewed` on a non-AU
  // storefront) — AGENTS.md's Multi-site section: never assume routing. The rail itself must not
  // build this prefix; this container does it once, here.
  const { buildUrl } = useMultiSite();
  // Also unconditional, same rules-of-hooks reason — but only ever given this shopper's real
  // tracked ids (and therefore only ever allowed to fire its own `getProducts` request, per its
  // own `enabled: cappedIds.length > 0`) when this particular instance is actually the
  // Recently-Viewed branch below. Every other recommender rendered on the same page (e.g. PDP's
  // own Might-Also-Like rail, mounted right alongside this one) would otherwise silently trigger
  // a second, unread product fetch whenever this browser already has tracked view history — the
  // same "network call fetching data nothing will ever read" problem fixed for
  // getRecommendations/getZoneRecommendations below, applied here to the fetch this branch adds.
  // `!isCartPage` too — see that constant's own comment above; Cart never renders this branch's
  // output, so fetching real product data for it there would be pure waste.
  const { products: recentlyViewedProducts } = useRecentlyViewedProductFetch(
    recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED && !isCartPage
      ? recentlyViewedIds
      : NO_RECENTLY_VIEWED_IDS,
  );

  useEffect(() => {
    // SFCC-83/84 build plan A6, bug fix #2 (2026-09-08 revision) — Recently Viewed no longer
    // reads Einstein's `recommendations` at all (see the branch further below), so calling
    // `getRecommendations`/`getZoneRecommendations` for it would be a real network request
    // fetching a response nothing ever reads. Skip both below for this one recommender; every
    // other recommender's fetch is unaffected.
    if (recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED) {
      return;
    }

    // Check if the component should fetch results or not. This is useful
    // when you are still waiting on additional data, like `products`.
    if (typeof shouldFetch === 'function' && !shouldFetch()) {
      return;
    }

    // Fetch either zone or recommender, but not both. If a zone and recommender
    // name are both provided, `zone` takes precendence.
    if (zone) {
      getZoneRecommendations(zone, _products);
      return;
    }
    if (recommender) {
      getRecommendations(recommender, _products);
      return;
    }
  }, [zone, recommender, _products]);

  useEffect(() => {
    // This is an optimization that eliminates superfluous rerenders/fetching by
    // keeping a copy of the `products` array prop in state for shallow comparison.
    if (!Array.isArray(products)) {
      return;
    }
    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
      setProducts(products);
    }
  }, [products]);

  useEffect(() => {
    if (isOnScreen && recommendations?.recs) {
      sendViewReco(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
      dataCloud.sendViewRecommendations(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
    }
  }, [isOnScreen, recommendations]);

  // SFCC-83 — Recently Viewed only. Every other recommender falls through to the unchanged
  // ProductScroller branch below. Moved ahead of the dead-check below (build plan A6, bug fix #3,
  // 2026-09-08 revision) — see this file's own module docblock for the full "why". In short: this
  // branch's cards no longer come from `recommendations` at all (see the effect above, bug fix
  // #2), so `recommendations`/`isLoading` stay at `useEinstein()`'s own untouched initial state
  // (`[]`/`false`) for this recommender, which would make the dead-check below evaluate `true`
  // unconditionally (via its `recommendations.length < 1` clause specifically, since
  // `recommendations` itself stays a truthy `[]`, never falsy) and return `null` regardless of
  // `hasRecentlyViewed` if this branch still ran after it. Every other recommender is unaffected
  // by the reordering — they still hit the exact same dead-check + ProductScroller path below,
  // unchanged, just after this check now short-circuits past them when it applies.
  if (recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED) {
    // Cart exclusion (2026-09-10, Marcel) — see the isCartPage constant's own comment above for
    // why this can't be expressed as a distinct recommender value. No rail, no title, no
    // placeholder — same treatment as the empty-state gate below, just for a different reason.
    if (isCartPage) {
      return null;
    }

    // AC 8's empty-state gate — see useRecentlyViewedHistory.ts's own docblock. No rail, no
    // title, no placeholder.
    if (!hasRecentlyViewed) {
      return null;
    }

    // `recentlyViewedProducts` is real, strongly-typed Commerce API data (see
    // recentlyViewedProductFetch.ts), unlike the old `recommendations.recs` chain this replaces —
    // nothing here is `any`, so (unlike the untouched `.find`/`.some`/`.map` callbacks elsewhere
    // in this file, which still read off `useEinstein()`'s untyped `recommendations`) no step of
    // this chain needs an explicit parameter-type annotation to satisfy `noImplicitAny`.
    const cards: ZimmProductCardProps[] = recentlyViewedProducts
      .map((product) => selectRecentlyViewedCard(product, formatPrice))
      .filter((card: RecentlyViewedCard | null): card is RecentlyViewedCard => card !== null)
      .map(
        (card: RecentlyViewedCard): ZimmProductCardProps => ({
          ...card,
          // Inert for this variation — ZimmProductCardContent never mounts when
          // variation: 'recentlyViewed' (zimmProductCard/index.tsx's
          // VARIATION_CONFIG.showContent). 'h3' matches the one other established value for
          // this same required field (product-list/productListCardMapper.ts).
          headingLevel: 'h3',
          variation: 'recentlyViewed',
        }),
      );

    // The See-Full-History link, finally wired in (was a stated "not yet built" gap on every
    // caller until now). Triggers when the shopper has more recently-viewed products
    // than fit in view at the *current* breakpoint — matching the AC's own "exceeds the visible
    // rail width" wording, which is viewport-relative, not a flat count. Compared against
    // `cards.length` (the full, unsliced count this container just built — up to
    // RECENTLY_VIEWED_HISTORY_MAX_STORED, 24), not the rail's own internal 5-item render slice,
    // since the question is "does more exist than is visible", not "did we cap the render".
    const showSeeAllLink = cards.length > visibleCardCount;

    return (
      // Ref-attachment point — see the module docblock's own isOnScreen/forwardRef note above for
      // why this wrapper exists at all. `{...props}` forwards the caller's own layout props (e.g.
      // PDP's `mx={{base: -4, md: -8, lg: 0}}`, Cart's `mx={{base: -4, sm: -6, lg: 0}}`) exactly
      // as the ProductScroller branch below already does — without it, this branch would render
      // inset inside the page's normal content padding while every sibling rail on the same page
      // bleeds edge-to-edge, and zimmRecentlyViewedRail.css.ts's own card-width math (e.g.
      // 201x2=402) assumes the full viewport width is actually available. `title` is passed
      // straight through, no `recommendations?.displayMessage` fallback — `recommendations` is
      // never populated for this branch (see above), and this component owns no copy of its own
      // (build plan A5/A6): the real title always comes from the caller.
      <Box ref={ref} {...(props as BoxProps)}>
        <ZimmRecentlyViewedRail
          title={title}
          cards={cards}
          seeAllHref={showSeeAllLink ? buildUrl(RECENTLY_VIEWED_ROUTE) : undefined}
          seeAllLabel={showSeeAllLink ? intl.formatMessage(messages.seeFullHistory) : undefined}
        />
      </Box>
    );
  }

  // The component should remove itself altogether if it has no recommendations
  // and we aren't loading any.
  if (!isLoading && (!recommendations || recommendations.length < 1)) {
    return null;
  }

  // TODO: DRY this handler when intl provider is available globally
  const addItemToWishlist = async (product: RecommendedProduct) => {
    try {
      if (!wishlist || !customerId) {
        return;
      }
      await createCustomerProductListItem.mutateAsync({
        parameters: {
          listId: wishlist.id,
          customerId,
        },
        body: {
          quantity: 1,
          productId: product.productId,
          public: false,
          priority: 1,
          type: 'product',
        },
      });

      toast({
        title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
        status: 'success',
        action: (
          // it would be better if we could use <Button as={Link}>
          // but unfortunately the Link component is not compatible
          // with Chakra Toast, since the ToastManager is rendered via portal
          // and the toast doesn't have access to intl provider, which is a
          // requirement of the Link component.
          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
            {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
          </Button>
        ),
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  const removeItemFromWishlist = async (product: RecommendedProduct) => {
    try {
      const wishlistItem = wishlist?.customerProductListItems?.find(
        (item: { productId?: string }) => item.productId === product.productId,
      );
      if (!wishlistItem || !wishlist || !customerId) {
        return;
      }
      await deleteCustomerProductListItem.mutateAsync({
        parameters: {
          customerId,
          itemId: wishlistItem.id,
          listId: wishlist.id,
        },
      });
      toast({
        title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
        status: 'success',
        id: product.productId,
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  return (
    <ProductScroller
      ref={ref}
      title={title || recommendations?.displayMessage}
      products={recommendations.recs}
      isLoading={isLoading}
      productTileProps={(product: RecommendedProduct) => ({
        onClick: () => {
          sendClickReco(
            {
              recommenderName: recommendations.recommenderName,
              __recoUUID: recommendations.recoUUID,
            },
            product,
          );
        },
        enableFavourite: true,
        isFavourite: wishlist?.customerProductListItems?.some(
          (item: { productId?: string }) => item.productId === product?.productId,
        ),
        onFavouriteToggle: (toBeFavourite: boolean) => {
          const action = toBeFavourite ? addItemToWishlist : removeItemFromWishlist;
          return action(product);
        },
      })}
      {...props}
    />
  );
};

export default RecommendedProducts;

import React from 'react';
import type { ReactNode } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';
import { useRecentlyViewedRailVisibleCount } from 'app/hooks/useRecentlyViewedRailVisibleCount';
import { ZimmProductCard } from '../zimmProductCard';
import type { ZimmProductCardProps } from '../zimmProductCard';

// Same `chakra(RouteLink)` wrap this component family already establishes for its own internal
// links (zimmProductCard/index.tsx's `MediaOnlyCardLink`, zimmProductCardContent/index.tsx's
// `ProductNameLink`) — used here for the See-Full-History link, which navigates to the SFCC-84
// Recently Viewed Full History page, an internal route, not an external URL.
const SeeAllLink = chakra(RouteLink);

export type ZimmRecentlyViewedRailProps = {
  /**
   * Typed as `ReactNode`, not `string` — this component owns no copy/intl (the container, A6,
   * does). **Styling resolved 2026-09-08** (was previously left unstyled pending confirmation —
   * live Storybook testing caught the resulting bug: the title rendered in the ambient body
   * weight, Futura Round 400, instead of the design's intended weight): this component now
   * applies `textStyle="heading3"` itself when rendering `title`, matching the exact spec
   * confirmed against the Full History page's own title bar this same session (Figma
   * `Default/h3-strong` — Futura Round, 16px/18 line-height, weight 500, letter-spacing -0.12px,
   * uppercase — cross-checked against this codebase's registered `heading3` token, an exact
   * match). Applying it here rather than requiring every caller to pre-style the title guarantees
   * the design intent regardless of what a caller passes; a caller supplying an already fully
   * styled element can still override any of this via its own more-specific styling.
   */
  title: ReactNode;
  /**
   * Rendered in the exact order received (AC 2: most-recent-first, left to right) — no sorting or
   * reordering happens here. Capped to `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS` for the current real
   * breakpoint regardless of length — a hard cap, not a "fits before scrolling" soft limit (see
   * that constant's own comment, app/constants/index.ts, and this component's own render-body
   * comment below for why the cap has to live here rather than in the request that produced this
   * array).
   */
  cards: readonly ZimmProductCardProps[];
  /** Href to the SFCC-84 Recently Viewed Full History page. The See-Full-History link only
   *  renders when this is provided — see the render body below. */
  seeAllHref?: string;
  /**
   * No default/fallback text is supplied when this is omitted while `seeAllHref` is provided —
   * this component owns no copy or intl (see the module docblock), so inventing an English
   * fallback here would risk shipping untranslated text on non-English storefronts. In real usage
   * the container (A6) is expected to always supply this alongside `seeAllHref`.
   */
  seeAllLabel?: string;
};

const ZIMM_RECENTLY_VIEWED_RAIL_RECIPE = 'ZimmRecentlyViewedRail';

/**
 * SFCC-83 — the Recently Viewed rail organism (build plan section A5). Purely presentational:
 * data arrives as props, no data-fetching, no `useEinstein`, no `useIntl` — see
 * .claude/rules/components.md's container/presentational split. The container (A6) is
 * responsible for building `cards` (via A3's Einstein-rec-to-card mapper), gating this
 * component's visibility (A4's `hasRecentlyViewed`), and supplying `title`/`seeAllLabel` copy.
 *
 * Structure mirrors Figma exactly: a `header` row (title left, the See-Full-History link right)
 * above a `group` of `ZimmProductCard`s. No rail-level arrow buttons — `ZimmProductCardMedia`
 * already carries its own intra-card carousel arrows, and a second set at the rail level would
 * collide with them (see zimmRecentlyViewedRail.css.ts's own docblock for the Figma node
 * evidence).
 *
 * **`group`'s horizontal scroll/scroll-snap (zimmRecentlyViewedRail.css.ts) is a narrow-viewport
 * safety net, not the "more cards exist, scroll to see them" mechanism it might look like.**
 * Confirmed with Marcel (2026-09-08): the per-breakpoint card count below is a hard cap — a
 * shopper on a real, design-reference-width device never has more cards to scroll to than the
 * cap allows; "more history exists" is surfaced via the See-Full-History link (the container's
 * own job), not via scrolling this rail further. The scroll/scroll-snap CSS stays
 * meaningful only for a real device narrower than the design reference itself (e.g. a phone
 * under ~402px), where the capped card count can still slightly overflow the actual viewport.
 *
 * `cards` is typed as the full `ZimmProductCardProps` union, matching this step's own given
 * component contract verbatim — this component therefore spreads each entry straight into
 * `ZimmProductCard` (`<ZimmProductCard {...card} />`) rather than forcing
 * `variation: 'recentlyViewed'` onto every card itself. In real usage every entry already carries
 * that variation by construction (A3's mapper produces `recentlyViewed`-shaped cards, matching
 * `variation: 'recentlyViewed'` in the type union — see zimmProductCard/index.tsx's
 * `ZimmProductCardRecentlyViewedVariation`) — this component trusts that contract rather than
 * re-asserting it, consistent with staying purely presentational.
 *
 * `data-testid="product-card"` / `data-product-id` on each rendered card come from
 * `ZimmProductCard`'s own root (zimmProductCard/index.tsx: "a DOM hook for QA automation/
 * analytics") — this component adds no additional per-card test hook of its own.
 */
export const ZimmRecentlyViewedRail = ({ title, cards, seeAllHref, seeAllLabel }: ZimmRecentlyViewedRailProps) => {
  const styles = useMultiStyleConfig(ZIMM_RECENTLY_VIEWED_RAIL_RECIPE, {});

  // Cap is enforced here, client-side, regardless of how many cards were passed in — the data
  // source (`useRecentlyViewedHistory` / `recentlyViewedProductFetch.ts`) does not itself honour
  // a requested limit, and per-breakpoint capping is this component's own presentational concern,
  // not the container's. Falls back to the smallest (base/mobile) count on the very first render
  // before the client-side media-query match resolves (see RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS's
  // own comment, app/constants/index.ts, for why this is a hard per-breakpoint cap, not a "fits
  // before scrolling" soft limit). A slice, never a sort — order is otherwise untouched (AC 2).
  //
  // `useRecentlyViewedRailVisibleCount()`, not a direct `useBreakpointValue` call (corrected
  // 2026-09-10 — see that hook's own docblock for the live-confirmed bug this closes): this
  // component's own Desktop card-width styling (zimmRecentlyViewedRail.css.ts's
  // `DESKTOP_UP_QUERY`) switches at 1024px, not this site's shared `breakpoints.xl` (1280px) that
  // `useBreakpointValue` would have resolved against — the two disagreeing meant a real, narrow
  // window (1024–1280px) where cards were already styled for 5 slots but only 3 were allowed to
  // render.
  const maxVisibleCards = useRecentlyViewedRailVisibleCount();
  const visibleCards = cards.slice(0, maxVisibleCards);

  // Second guard behind A4's own visibility gate, which lives in the container, not here — an
  // empty rail renders nothing at all, not an empty shell.
  if (visibleCards.length === 0) {
    return null;
  }

  return (
    <chakra.div __css={styles.container} data-testid="recently-viewed-rail">
      <chakra.div __css={styles.header}>
        {/* flex/minWidth match Figma's own title node (flex: 1 0 0, min-w-px) — grows to fill
            whatever `header`'s own gap + the link's width don't claim, and can shrink below its
            own text's intrinsic width rather than force an overflow. See zimmRecentlyViewedRail.css.ts's
            own "TITLE/LINK SPACING" docblock section. */}
        <chakra.span textStyle="heading3" flex="1 0 0" minWidth={0}>
          {title}
        </chakra.span>
        {seeAllHref && seeAllLabel && (
          <SeeAllLink to={seeAllHref} textStyle="linkLg" __css={styles.seeAllLink}>
            {seeAllLabel}
          </SeeAllLink>
        )}
      </chakra.div>
      <chakra.div __css={styles.group} data-testid="recently-viewed-rail-group">
        {visibleCards.map((card) => (
          <chakra.div key={card.id} __css={styles.card}>
            <ZimmProductCard {...card} />
          </chakra.div>
        ))}
      </chakra.div>
    </chakra.div>
  );
};

import type { SystemStyleObject } from '@chakra-ui/react';
import { breakpoints } from 'app/theme/foundation';

/**
 * Recipe for the Recently Viewed Full History grid organism (SFCC-84), build plan section B1.
 * Design source: `Zimmermann_Designs` file, `3332:35655` → `Container` → `PLP Bar desktop`
 * (`3332:37131`, 1440×75, title left / item-count right) + `Sidebar` (`3332:35664`, four stacked
 * `Products Module Desktop` instances, each 1440×606, containing `Products S Desktop` cards at
 * 288×542, x = 0/384/768/1152 — a `plp`-shaped `ZimmProductCard`, not a new card; see index.tsx's
 * own `cards` JSDoc for the `variation: 'plp'` citation). **This source is provisional per
 * Marcel's 2026-09-04 precedence rule** (it is not a PDP/Recently Viewed node in the authoritative
 * `Zimmermann_Design_System_2026` file `ZimmRecentlyViewedRail`'s own recipe uses) — that ranking
 * is unaffected by the "confirmed" values below; see index.tsx's own module docblock for why both
 * things are true at once.
 *
 * Parts: `container`, `header`, `grid` — reconciled against index.tsx's own `useMultiStyleConfig`
 * reads by `ui-kits/recipeParts.test.ts`. No `card` part (contrast
 * `zimmRecentlyViewedRail.css.ts`'s own `card` part): the rail fixes a per-breakpoint PIXEL width
 * on each item because it lays out a horizontally-scrolling flex row with no requirement to fill
 * the viewport exactly. This is a real grid, not a scroller — `grid` below uses fractional
 * (`1fr`) column tracks instead, so each card's rendered width falls out of the container width
 * divided across the current column count with nothing extra to style per card; `ZimmProductCard`
 * itself still has no width/height opinion of its own (`zimmProductCard.css.ts`), same precedent
 * the rail's own docblock already establishes.
 *
 * HORIZONTAL GAP — three tiers, NOT a single uniform value (corrected 2026-09-10, closing a real
 * bug: a fuller page-node audit found the previous single 96px-everywhere value was only ever
 * confirmed for Desktop; Tablet and Mobile each have their own, different, real Figma value that
 * was never actually checked before this correction). Checked directly against the real page
 * frames' own card-group children:
 *   - Desktop (unchanged, still confirmed via the two independent sources this paragraph already
 *     cited): 96px, GENUINELY UN-TOKENISED — see `GRID_CARD_GAP_DESKTOP`'s own comment below for
 *     the full pending-token reasoning, unaffected by this correction.
 *   - Tablet (`9560:137692`, 3-card row, 834px wide): 80px, bound to a real Figma variable
 *     (`alias/space/2000`) — and unlike Desktop's 96px, this one DOES have a real registered
 *     equivalent: `--zimm-scale-5xl` (`spacing['5xl']`, `foundation/spacing.ts`), confirmed
 *     directly, no pending-token gap here.
 *   - Mobile (`9560:138463`, 2×2 grid): 40px, bound to a real Figma variable
 *     (`alias/space/gap/1000`) — also a real registered equivalent, `--zimm-scale-1000`
 *     (`spacing['3xl']`), same as this file's own `HEADER_PADDING_DESKTOP` constant below.
 * `columnGap` below is now set per-breakpoint instead of once at the base level.
 *
 * VERTICAL (ROW) GAP — 64px, and UNLIKE the horizontal gap above, this one has a real registered
 * token: `--zimm-scale-1600` (`zimmTokens.ts`), which resolves to `spacing['4xl']` —
 * independently verified directly against `foundation/spacing.ts` (`'4xl': '4rem'`, i.e. 64px),
 * not assumed from the build plan's own citation of it. Matches the real bound Figma variable
 * `section/4xl` (Designs file) / `alias/space/1600` (System file) per build plan §B1. Per this
 * step's own instruction, a REAL token is referenced directly (`var(--zimm-scale-1600)`) rather
 * than re-declared as a named constant — there is nothing to name here that isn't already named.
 *
 * COLUMN COUNT PER BREAKPOINT — three tiers: 2 (Mobile, below `breakpoints.md`), 3 (Tablet,
 * `breakpoints.md` up), 4 (Desktop, `breakpoints.xl` up).
 *   - `GRID_COLUMNS_BASE = 2` (Mobile only — matches the "2-up on the smallest breakpoint"
 *     convention `overrides/app/pages/product-list/index.tsx`'s own `SimpleGrid columns={[2, 2,
 *     4, 5]}` already establishes elsewhere in this codebase).
 *   - `GRID_COLUMNS_TABLET = 3` — originally Marcel's own direct figure (2026-09-08), not a
 *     re-derived Figma reading, since this grid's provisional design source (cited above) has no
 *     Tablet-specific node of its own. Corrected 2026-09-10: a fuller page-node audit (the same
 *     pass that fixed this file's own HORIZONTAL GAP section) checked the real Tablet page frame
 *     directly (`9560:137692`, cited above for its gap value) and found it also shows exactly 3
 *     fluid-width cards per row — the figure was already corroborated, this comment just never
 *     connected the two. Confirmed, not merely instructed, as of this correction.
 *   - `GRID_COLUMNS_DESKTOP = 4` — unchanged, the one confirmed-via-Figma value (cited above).
 *
 * HEADER HEIGHT — deliberately UNSET (contrast `zimmRecentlyViewedRail.css.ts`'s own
 * `HEADER_HEIGHT_MOBILE`/`DESKTOP`). The one Figma reading available (`3332:37131`, 75px,
 * Desktop-only) has no corroborating Mobile/Tablet reading to pair it with, and neither this
 * step's brief nor the build plan's own B1 pass criteria asks for a fixed header height at all —
 * unlike the rail, where two independent node heights (Mobile+Tablet-covering 56px, Desktop 96px)
 * were both explicitly supplied. Setting one anyway from a single, viewport-unconfirmed number
 * would be inventing a cross-viewport claim this session has no evidence for. `header` below sizes
 * itself from its own content instead (`display: flex`, vertically centred) — the same
 * "leave it simple, comment why" instruction this docblock's COLUMN COUNT section above follows
 * for the same underlying reason (one Desktop-only reading, no Tablet/Mobile counterpart).
 *
 * TITLE ROW PADDING — corrected 2026-09-10, closing a real, live-confirmed bug (Figma-vs-code
 * audit requested by Marcel, same pass that found and fixed the sibling Rail's own header padding
 * bug). The paragraph this replaces called the horizontal inset "deliberately zero... flagged for
 * confirmation" pending a real page context — that page context now exists
 * (`overrides/app/pages/recentlyViewed/index.tsx`), and checking the header row directly against
 * the three real page-composition frames (`9551:110758` Desktop, `9560:137691` Tablet,
 * `9560:138462` Mobile, same `Zimmermann_Designs` file) found the actual values are neither zero
 * nor the asymmetric split the previous revision derived from a single provisional bar node
 * (`3332:37131`) — see "Header padding" below, which replaces both the old "Header vertical
 * padding" and "Header horizontal insets" sections entirely.
 */

// Horizontal card-to-card gap, Desktop only now — see this file's own "HORIZONTAL GAP" docblock
// section above for the full per-breakpoint correction. rem, not px, matching
// zimmRecentlyViewedRail.css.ts's CARD_WIDTH_MOBILE/TABLET/DESKTOP precedent for a sizing
// (non-hairline) dimension with no foundation token yet.
const GRID_CARD_GAP_DESKTOP = '6rem'; // 96px — confirmed Figma value, checked at two independent sources (40000301:11694 "Product Card Group" master, Size=Desktop/Display=4, node 40000307:12446; and the page-level instance 3332:35655). No --zimm-scale-* equivalent (nearest neighbours: named scale 5xl=80px / 6xl=128px; numeric alias 1600=64px jumps straight to 3500=140px) — pending promotion to foundation/spacing.ts or sizes.ts by the UI designer.

// Column counts per breakpoint — see this file's own "COLUMN COUNT PER BREAKPOINT" docblock
// section above for the full reasoning and sourcing (Desktop is a confirmed Figma reading; Mobile
// and Tablet are Marcel's own direct figures, 2026-09-08, not re-derived design-asset readings).
const GRID_COLUMNS_BASE = 2; // Mobile only (below breakpoints.md) — Marcel, 2026-09-08.
const GRID_COLUMNS_TABLET = 3; // breakpoints.md up, below breakpoints.xl — Marcel, 2026-09-08.
const GRID_COLUMNS_DESKTOP = 4; // breakpoints.xl and up — confirmed (Figma nodes cited in the docblock above).

// Same Tablet/Desktop query convention (name and breakpoint) as zimmRecentlyViewedRail.css.ts's
// own identically-named constants.
const TABLET_UP_QUERY = `@media (min-width: ${breakpoints.md})`; // 768px
const DESKTOP_UP_QUERY = `@media (min-width: ${breakpoints.xl})`; // 1280px — the confirmed 4-up/288px reading itself comes from a 1440px Figma frame, inside this tier.

// Content max-width — fixed 2026-09-08, same root cause and same fix shape as
// zimmRecentlyViewedRail.css.ts's own identical bug found via live testing the same day: with no
// cap, `container`'s `width: '100%'` (and `grid`'s own, below) stretch to whatever width the page
// actually provides — confirmed via Storybook screenshot that this genuinely oversizes every card
// beyond the confirmed 288px reading, not just a cosmetic nit. 1440px is the same confirmed value
// `GRID_CARD_GAP_DESKTOP`'s own docblock derives from (4 x 288px cards + 3 x 96px gaps) — restated here as
// a width cap rather than a per-card value. Desktop-only, matching the fact that the 4-column
// layout itself only applies from this breakpoint up; neither the Mobile (2-column) nor Tablet
// (3-column) tier has a confirmed reference *width* to cap against — Marcel's own figures above
// are column counts, not card widths or a max-width reading — so both stay fluid, same "don't
// guess" reasoning as the column counts' own docblock section.
// audit-allow: derived composite (already-pending card width x confirmed column/gap counts),
// not itself a value with any promotable foundation-token equivalent.
const GRID_CONTENT_MAX_WIDTH_DESKTOP = '90rem'; // 1440px = (288px x 4 cards) + (96px x 3 gaps)

// Header padding — corrected 2026-09-10, replacing both the old "Header vertical padding" and
// "Header horizontal insets" sections (see the module docblock's own "TITLE ROW PADDING" note for
// the full correction narrative). Checked directly against the three real page-composition frames
// rather than the single provisional bar node the previous revision relied on:
//   - Desktop (`9551:110758`): 40px padding on all four sides, symmetric -- not the previous
//     asymmetric 40px-start/180px-end split, which was derived from that bar's own inner content
//     box being narrower than the frame for unrelated layout reasons, not a real padding reading.
//   - Tablet (`9560:137691`) / Mobile (`9560:138462`), identical: 32px horizontal, 20px vertical,
//     symmetric -- not the previous zero horizontal / 32px vertical (the 32px vertical value was
//     real but only for Desktop; Tablet/Mobile's own real vertical figure is smaller, 20px).
// All three real values map onto already-registered tokens: `--zimm-scale-1000` (40px),
// `--zimm-scale-800` (32px), `--zimm-scale-500` (20px, spacing['l']) -- confirmed directly against
// zimmTokens.ts, not assumed.
const HEADER_PADDING_INLINE = 'var(--zimm-scale-800)'; // 32px -- Tablet/Mobile
const HEADER_PADDING_BLOCK = 'var(--zimm-scale-500)'; // 20px -- Tablet/Mobile
const HEADER_PADDING_DESKTOP = 'var(--zimm-scale-1000)'; // 40px -- Desktop, all four sides

export const ZimmRecentlyViewedGrid = {
  parts: ['container', 'header', 'grid'],

  baseStyle: (): Record<string, SystemStyleObject> => ({
    container: {
      width: '100%',
      marginInline: 'auto',
      [DESKTOP_UP_QUERY]: {
        maxWidth: GRID_CONTENT_MAX_WIDTH_DESKTOP,
      },
    },

    header: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      paddingInline: HEADER_PADDING_INLINE,
      paddingBlock: HEADER_PADDING_BLOCK,
      [DESKTOP_UP_QUERY]: {
        paddingInline: HEADER_PADDING_DESKTOP,
        paddingBlock: HEADER_PADDING_DESKTOP,
      },
    },

    grid: {
      display: 'grid',
      width: '100%',
      // `minmax(0, 1fr)`, not bare `1fr` (fixed 2026-09-10, closing a real, live-confirmed bug).
      // Bare `1fr` is shorthand for `minmax(auto, 1fr)` — a track's floor is its own content's
      // min-content size, not zero. That's invisible normally, but the size-chip row (revealed on
      // hover; see zimmProductCard.css.ts's own hoverRevealsSizeSelector block) carries a genuine,
      // non-shrinking minimum width once it enters layout (fixed-width chips, fixed `gap`, no
      // wrap) — confirmed live (Marcel, three screenshots: bug present at the narrow end of every
      // breakpoint tier — small desktop/small tablet/smaller mobile — absent at the wide end,
      // every time). At a narrow-enough column width, that minimum exceeds the column's own 1fr
      // share, so the bare-`1fr` track grows to fit it — widening every card sharing that column,
      // not just the hovered one, since a grid track's width is shared across every row. The
      // card's own image then grows too, but only as a downstream effect: `zimmProductCardMedia.
      // css.ts`'s `slide` part is `aspectRatio`-locked to its own width, so a wider column
      // mechanically produces a taller image regardless of which image (base or hover-swap) is
      // showing — confirmed directly against that file's own hover-swap implementation (both
      // images `position: absolute; inset: 0`, sized only by the aspect-ratio-locked container,
      // never by their own intrinsic size), which rules out the image swap itself as an
      // independent cause. `minmax(0, 1fr)` tells the grid the track's floor is zero instead of
      // "whatever a child needs" — the column stays at its fair share regardless of what a
      // hover-revealed child demands. Same fix family as this codebase's own existing `minWidth: 0`
      // guards on flex children (e.g. zimmProductCardContent.css.ts's `nameLink`/`priceWrapper`),
      // just expressed at the grid-track level instead.
      gridTemplateColumns: `repeat(${GRID_COLUMNS_BASE}, minmax(0, 1fr))`,
      // Per-breakpoint now — see this file's own "HORIZONTAL GAP" docblock section above for the
      // correction. Mobile/Tablet use real registered tokens directly; only Desktop's 96px is a
      // pending-token named constant.
      columnGap: 'var(--zimm-scale-1000)', // 40px — Mobile
      // Real registered token, referenced directly — see this file's own "VERTICAL (ROW) GAP"
      // docblock section above for why this one is NOT a named constant, unlike GRID_CARD_GAP_DESKTOP.
      rowGap: 'var(--zimm-scale-1600)', // 64px
      [TABLET_UP_QUERY]: {
        gridTemplateColumns: `repeat(${GRID_COLUMNS_TABLET}, minmax(0, 1fr))`,
        columnGap: 'var(--zimm-scale-5xl)', // 80px
      },
      [DESKTOP_UP_QUERY]: {
        gridTemplateColumns: `repeat(${GRID_COLUMNS_DESKTOP}, minmax(0, 1fr))`,
        columnGap: GRID_CARD_GAP_DESKTOP,
      },
    },
  }),
};

